<template><ReaderLayout><section class="profile"><p class="eyebrow">账户设置</p><h1>我的资料</h1><form @submit.prevent="save"><label>昵称<input v-model="form.nickName" /></label><label>头像地址<input v-model="form.userPhoto" placeholder="可选" /></label><label>性别<select v-model="form.userSex"><option value="0">保密</option><option value="1">男</option><option value="2">女</option></select></label><label>生日<input v-model="form.userBirthday" placeholder="yyyy-MM-dd" /></label><label>手机号<input v-model="form.userPhone" /></label><label>邮箱<input v-model="form.userEmail" type="email" /></label><button class="primary-button">保存资料</button></form></section></ReaderLayout></template>
<script>
import { onMounted, reactive } from 'vue'; import ReaderLayout from '@/components/common/ReaderLayout.vue'; import { getMe, updateMe } from '@/api/me'; import { getUser, setUser } from '@/utils/auth'; import { ElMessage } from 'element-plus'
export default { name: 'Me', components: { ReaderLayout }, setup() { const form = reactive({ nickName: '', userPhoto: '', userSex: '0', userBirthday: '', userPhone: '', userEmail: '' }); onMounted(async () => { const result = await getMe(); const user = result.data || {}; Object.assign(form, { nickName: user.nickName || '', userPhoto: user.userPhoto || '', userSex: String(user.userSex ?? 0), userBirthday: user.userBirthday || '', userPhone: user.userPhone || '', userEmail: user.userEmail || '' }); setUser(user) }); const save = async () => { const payload = { nickName: form.nickName, userPhoto: form.userPhoto, userSex: Number(form.userSex), userPhone: form.userPhone, userEmail: form.userEmail }; if (form.userBirthday) payload.userBirthday = form.userBirthday; await updateMe(payload); setUser({ ...getUser(), ...payload }); ElMessage.success('资料已保存') }; return { form, save } } }
</script>


